"""Calculate monthly payroll from the supplied cleaning-service CSV files."""

import ast
import csv
import json
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATASET = Path("/app/dataset")


def _read_csv(name):
    with (DATASET / name).open(encoding="utf-8", newline="") as file:
        return list(csv.DictReader(file))


def _task_ids(value):
    """Repair missing outer brackets while preserving the recorded task IDs."""
    value = value.strip()
    if not value.startswith("["):
        value = "[" + value
    if not value.endswith("]"):
        value += "]"
    try:
        parsed = ast.literal_eval(value)
    except (ValueError, SyntaxError):
        return []
    if not isinstance(parsed, list):
        return []
    return [item for item in parsed if type(item) is int]


def _first_weekday(year, month, weekday):
    first = date(year, month, 1)
    return first + timedelta(days=(weekday - first.weekday()) % 7)


def _billing_start(work_date, weekday):
    start = _first_weekday(work_date.year, work_date.month, weekday)
    if work_date < start:
        previous_month = work_date.replace(day=1) - timedelta(days=1)
        start = _first_weekday(
            previous_month.year, previous_month.month, weekday
        )
    return start


def answer() -> dict[str, list[int]]:
    employees = _read_csv("employees.csv")
    rates = {row["PESEL"]: Decimal(row["hourly_rate"]) for row in employees}
    task_pay = {
        int(row["task_id"]): Decimal(row["pay_per_completion"])
        for row in _read_csv("tasks.csv")
    }

    shifts = []
    seen = set()
    for row in _read_csv("timesheet.csv"):
        pesel = row["employee_id"]
        # Unknown IDs have no employee-master record. Their shifts overlap
        # existing employees' shifts and cannot safely be assigned to them.
        if pesel not in rates:
            continue
        try:
            work_date = date.fromisoformat(row["date"])
            hours = Decimal(row["hours_worked"])
        except (ValueError, ArithmeticError):
            # April 31 and June 31 have no unambiguous replacement date.
            continue
        if not hours.is_finite() or not Decimal(0) <= hours <= Decimal(24):
            continue

        # Duplicate shifts received different row IDs; ignore that field.
        key = tuple((field, value) for field, value in row.items() if field != "id")
        if key in seen:
            continue
        seen.add(key)
        shifts.append((pesel, work_date, hours, _task_ids(row["performed_tasks"])))

    if not shifts:
        return {pesel: [] for pesel in rates}

    weekday = min(shift[1] for shift in shifts).weekday()
    totals = defaultdict(Decimal)
    first_period = min(_billing_start(shift[1], weekday) for shift in shifts)
    last_period = max(_billing_start(shift[1], weekday) for shift in shifts)

    for pesel, work_date, hours, tasks in shifts:
        period = _billing_start(work_date, weekday)
        # salary_amount is cumulative base pay, not the pay for this row.
        # Recompute bonuses: unknown tasks and erroneous stored bonuses
        # must not affect pay for the valid completed tasks.
        bonus = sum((task_pay.get(task, Decimal(0)) for task in tasks), Decimal(0))
        totals[pesel, period] += hours * rates[pesel] + bonus

    periods = []
    period = first_period
    while period <= last_period:
        periods.append(period)
        year, month = period.year, period.month + 1
        if month == 13:
            year, month = year + 1, 1
        period = _first_weekday(year, month, weekday)

    return {
        pesel: [
            int(totals[pesel, period].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for period in periods
        ]
        for pesel in rates
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as file:
        json.dump(answer(), file, ensure_ascii=False, indent=2)
        file.write("\n")
